def field_bounds(rate_map, peak_idx, peak_val, frac=0.2):
    """Return (left_idx, right_idx) where rate first drops below frac * peak."""
    thr = frac * peak_val
    left = peak_idx
    while left > 0 and rate_map[left] >= thr:
        left -= 1
    right = peak_idx
    while right < len(rate_map) - 1 and rate_map[right] >= thr:
        right += 1
    return left, right

